import{_ as t,o as r,c as n,ah as s}from"./chunks/framework.C-FRNfAJ.js";const m=JSON.parse('{"title":"Comptes et rôles","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/administrateur/comptes-et-roles.md","filePath":"src/guide/administrateur/comptes-et-roles.md"}'),a={name:"guide/administrateur/comptes-et-roles.md"};function o(i,e,l,d,u,p){return r(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="comptes-et-roles" tabindex="-1">Comptes et rôles <a class="header-anchor" href="#comptes-et-roles" aria-label="Permalink to &quot;Comptes et rôles&quot;">​</a></h1><p>L&#39;Administrateur a accès à toute l&#39;application. Sa rubrique <strong>Administration</strong> regroupe la gestion des comptes, des rôles et des réglages.</p><h2 id="les-demandes-de-role" tabindex="-1">Les demandes de rôle <a class="header-anchor" href="#les-demandes-de-role" aria-label="Permalink to &quot;Les demandes de rôle&quot;">​</a></h2><p><strong>Administration → Demandes de rôle</strong> est l&#39;écran des personnes qui valident des rôles ; l&#39;Administrateur peut tous les valider, en plus de l&#39;acteur désigné pour chacun, afin qu&#39;aucune demande ne reste bloquée par un poste vacant.</p><table tabindex="0"><thead><tr><th>Rôle</th><th>Valide en principe</th></tr></thead><tbody><tr><td>Formateur Principal, Coach-Tuteur</td><td>Coordinateur pédagogique</td></tr><tr><td>Conseiller admissions, Chargés, Direction, Coordinateur</td><td>Administrateur</td></tr><tr><td>Apporteur d&#39;affaires, Partenaire marketing, Financeur</td><td>Chargé de partenariats</td></tr><tr><td>Financeur d&#39;événement</td><td>Chargé d&#39;événements</td></tr><tr><td>Porteur de projet</td><td>Chargé d&#39;incubation, à la rétention du projet</td></tr></tbody></table><p>L&#39;écran comporte :</p><ul><li><strong>En attente de décision</strong> : chaque demande avec le message de la personne. <strong>Valider</strong> active le rôle aussitôt et prévient la personne par e-mail ; <strong>Refuser</strong> exige un <strong>motif</strong>, envoyé par e-mail. Un refus ne touche pas les autres rôles de la personne ;</li><li><strong>Titulaires</strong> : les comptes qui ont un rôle que vous validez, avec la date et l&#39;auteur de la validation, <strong>Retirer</strong> (avec un motif) ;</li><li><strong>Attribuer un rôle</strong> directement à un compte existant, sans demande préalable.</li></ul><p>Personne ne décide de ses <strong>propres demandes</strong> et ne retire <strong>son propre rôle</strong>.</p><h2 id="les-utilisateurs" tabindex="-1">Les utilisateurs <a class="header-anchor" href="#les-utilisateurs" aria-label="Permalink to &quot;Les utilisateurs&quot;">​</a></h2><p><strong>Administration → Utilisateurs</strong> liste les comptes, que l&#39;on cherche par nom ou e-mail, filtre par rôle, et <strong>exporte en CSV</strong> (en respectant la recherche en cours). Pour chacun : ses rôles, son statut, son état de vérification et sa <strong>dernière connexion</strong>.</p><ul><li><strong>Nouvel utilisateur</strong> crée un compte, par exemple pour un membre du personnel, avec ses rôles. À la création, vous attribuez n&#39;importe quel rôle, même un rôle que quelqu&#39;un d&#39;autre valide en principe. Un nouveau compte ne peut pas être Financeur, car c&#39;est un compte individu.</li><li><strong>Modifier</strong> met à jour le nom, l&#39;e-mail, le téléphone (au format international) et, si vous le souhaitez, le mot de passe ; le champ vide conserve l&#39;actuel. Chaque modification est <strong>journalisée</strong>. <strong>Gérer les rôles</strong> renvoie aux demandes de rôle.</li><li><strong>Supprimer</strong> retire définitivement le compte. Vous ne pouvez pas supprimer <strong>votre propre compte</strong> depuis ce panneau.</li></ul><h3 id="les-statuts-d-un-compte" tabindex="-1">Les statuts d&#39;un compte <a class="header-anchor" href="#les-statuts-d-un-compte" aria-label="Permalink to &quot;Les statuts d&#39;un compte&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Statut</th><th>Signification</th></tr></thead><tbody><tr><td>Actif</td><td>Compte normal</td></tr><tr><td>Suspendu</td><td>Impayé après J+30 : aucune action payante, quel que soit le module, et plus d&#39;accès à Sève. Le paiement rétablit tout</td></tr><tr><td>Canopé</td><td>Ancien apprenant certifié</td></tr><tr><td>Désactivé</td><td>Inactif depuis un an : les données sont conservées et le compte se réactive à la prochaine connexion</td></tr></tbody></table><h2 id="les-comptes-organisation" tabindex="-1">Les comptes organisation <a class="header-anchor" href="#les-comptes-organisation" aria-label="Permalink to &quot;Les comptes organisation&quot;">​</a></h2><p><strong>Administration → Comptes organisation</strong> liste les demandes de transformation d&#39;un compte individu en compte organisation, <strong>à l&#39;Administrateur seul</strong>.</p><ul><li><strong>En attente de décision</strong> : le compte, la raison sociale demandée, le <strong>justificatif</strong> (RCCM ou équivalent, à télécharger), le message de la personne.</li><li><strong>Valider</strong> : le compte prend la raison sociale comme <strong>nom</strong>, l&#39;<strong>ancien nom est conservé</strong> dans la demande et dans le journal, et la personne est prévenue. Son historique reste consultable en lecture seule.</li><li><strong>Refuser</strong> : un <strong>motif</strong> est obligatoire, envoyé par e-mail ; le compte reste inchangé et peut redemander.</li></ul><p>Vous ne décidez pas votre propre demande. Un compte qui a déjà une demande en cours ne peut pas en déposer une seconde, et un compte organisation ne peut pas en redemander.</p>',17)])])}const g=t(a,[["render",o]]);export{m as __pageData,g as default};
